fun hoursText(milliseconds: Double, seconds: Boolean = false): String {
    val count = (milliseconds.coerceAtLeast(0.0) / 1000).toLong()
    val result = String.format(Locale.US, "%02d:%02d", count / 3600, count / 60 % 60)
    return if (seconds) result + String.format(Locale.US, ":%02d", count % 60) else result
}


