@Composable
fun PeriodChooser(period: PayPeriod, startDay: Int, current: PayPeriod, onSelect: (PayPeriod) -> Unit) {
    var picker by remember { mutableStateOf(false) }
    val ending = YearMonth.from(period.end)
    Column(Modifier.fillMaxWidth()) {
        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
            TextButton(enabled = ending.year > 1900 || ending.monthValue > 1, onClick = {
                onSelect(periodEndingIn(ending.minusMonths(1), startDay))
            }) { Text(tr(R.string.text_d61f7f639f)) }
            TextButton(modifier = Modifier.weight(1f), onClick = { picker = true }) {
                Text(period.end.format(DateTimeFormatter.ofPattern("MMMM yyyy", appLocale)), fontWeight = FontWeight.Bold)
                AppIcon(R.drawable.ic_expand_more)
            }
            TextButton(enabled = ending.year < 2100 || ending.monthValue < 12, onClick = {
                onSelect(periodEndingIn(ending.plusMonths(1), startDay))
            }) { Text(tr(R.string.text_28890b291d)) }
        }
        Text("${period.from.format(dateFormat)} – ${period.end.format(dateFormat)}", style = MaterialTheme.typography.bodySmall,
            modifier = Modifier.align(Alignment.CenterHorizontally))
        if (period != current) TextButton(onClick = { onSelect(current) }, modifier = Modifier.align(Alignment.CenterHorizontally)) {
            Text(tr(R.string.period_current))
        }
    }
    if (picker) MonthYearDialog(period, startDay, current, onDismiss = { picker = false },
        onSelect = { onSelect(it); picker = false })
}

@Composable
fun MonthYearDialog(period: PayPeriod, startDay: Int, current: PayPeriod, onDismiss: () -> Unit, onSelect: (PayPeriod) -> Unit) {
    var year by rememberSaveable { mutableStateOf(YearMonth.from(period.end).year.toString()) }
    var month by rememberSaveable { mutableIntStateOf(period.end.monthValue) }
    val parsedYear = year.asLocalizedInt()?.takeIf { it in 1900..2100 }
    val selected = parsedYear?.let { periodEndingIn(YearMonth.of(it, month), startDay) }
    AlertDialog(onDismissRequest = onDismiss, title = { Text(tr(R.string.period_choose)) }, text = {
        Column(Modifier.verticalScroll(rememberScrollState()), verticalArrangement = Arrangement.spacedBy(8.dp)) {
