                singleLine = true, isError = parsedYear == null, modifier = Modifier.fillMaxWidth(),
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number))
            if (parsedYear == null) Text(tr(R.string.period_year_hint), color = MaterialTheme.colorScheme.error)
            (1..12).chunked(3).forEach { months -> Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(6.dp)) {
