                }) }
            } }
            selected?.let { Text("${it.from.format(dateFormat)} – ${it.end.format(dateFormat)}", fontWeight = FontWeight.Bold) }
            TextButton(onClick = { onSelect(current) }) { Text(tr(R.string.period_current)) }
        }
    }, confirmButton = { TextButton(enabled = selected != null, onClick = { selected?.let(onSelect) }) { Text(tr(R.string.period_apply)) } },
