@Composable
fun HistoryScreen(data: AppData, onManual: () -> Unit, onEdit: (Shift) -> Unit, onDelete: (Shift) -> Unit, enabled: Boolean, onMessage: (String)->Unit) {
    var monthString by rememberSaveable { mutableStateOf(YearMonth.from(periodFor(LocalDate.now(israelZone), data.settings.periodStartDay).from).toString()) }
    var location by rememberSaveable { mutableStateOf("הכול") }
    val month = YearMonth.parse(monthString)
    val period = periodFromMonth(month, data.settings.periodStartDay)
    val summary = remember(data, period) { summarize(data, period) }
    val days = summary.days.sortedByDescending { it.day }
    LazyColumn(contentPadding = PaddingValues(20.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
        item { PeriodChooser(period, data.settings.periodStartDay, periodFor(LocalDate.now(israelZone),data.settings.periodStartDay)) { monthString = YearMonth.from(it.from).toString() } }
        item {
            Button(onClick = onManual, enabled = enabled, modifier = Modifier.fillMaxWidth()) { Text(tr(R.string.text_57b4cda969)) }
            Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) { listOf("הכול", OFFICE, HOME).forEach { v -> FilterChip(location == v, onClick = { location = v }, label = { Text(if (v == "הכול") tr(R.string.filter_all) else locationLabel(v)) }) } }
            Text(tr(if(data.settings.overtimeMode=="DAILY")R.string.text_7149f2ed6a else R.string.ot_location_hint), style = MaterialTheme.typography.bodySmall)
            ShiftExportButton(data,period,location.takeIf { it!="הכול" },enabled && (days.any { day -> day.parts.any { location=="הכול" || it.shift.location==location } } || (location=="הכול" && summary.leave.isNotEmpty())),onMessage)
            Text(overtimeRuleDescription(data.settings),style=MaterialTheme.typography.bodySmall)
            Text(tr(R.string.export_filter_hint),style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)
            Text(tr(R.string.leave_export_hint),style=MaterialTheme.typography.bodySmall)
        }
        if (data.active != null) item { Text(tr(R.string.text_3579e0306b), color = MaterialTheme.colorScheme.primary) }
        if (days.isEmpty()) item { Text(tr(R.string.text_643cae9ae3)) }
        items(days, key = { it.day.toString() }) { day ->
            val parts = day.parts.filter { location == "הכול" || it.shift.location == location }
            if (parts.isNotEmpty()) ExpandableCard(day.day.format(DateTimeFormatter.ofPattern("EEEE dd/MM/yyyy", appLocale)),summary={
                Text(parts.map { locationLabel(it.shift.location) }.distinct().joinToString(" · "),style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)
                Metric(tr(R.string.text_a3756d29d2),hoursText(day.totalMs))
                if(data.setupComplete)Metric(tr(R.string.text_dda62e1cc9),hoursText(day.tierMs.sum()))
                if(location!="הכול")Metric(tr(R.string.text_c24fae5be3),hoursText(parts.sumOf { it.netMs }))
            }) {
                parts.forEach { p ->
                    val s = p.shift
                    HorizontalDivider()
                    Text(locationLabel(s.location), fontWeight = FontWeight.Bold)
                    Text(tr(R.string.text_c386f7af9f, localTime(s.start).format(dateFormat), localTime(s.start).format(clockFormat)))
                    Text(tr(R.string.text_d3fcfb1a78, localTime(s.end).format(dateFormat), localTime(s.end).format(clockFormat)))
                    if (s.reason.isNotBlank()) Text(s.reason)
                    if (s.note.isNotBlank()) Text(s.note, color = MaterialTheme.colorScheme.error)
                    RecordActions(s,enabled,onEdit,onDelete)
                }
                HorizontalDivider(Modifier.padding(top = 8.dp))
                Text(tr(R.string.text_0826149cf1), fontWeight = FontWeight.Bold)
                if (location != "הכול") Metric(tr(R.string.text_c24fae5be3), hoursText(parts.sumOf { it.netMs }))
                if (data.setupComplete) {
                    Metric(tr(R.string.text_07b643f83a), hoursText(day.regularMs))
                    Metric(tr(R.string.text_dda62e1cc9), hoursText(day.tierMs.sum()))
                    day.tierMs.forEachIndexed { i, ms -> if (ms > 0) Metric("${number(data.settings.tiers[i].percent)}%", hoursText(ms)) }
                }
            }
        }
    }
}

@Composable
fun DateTimeField(label: String, value: LocalDateTime, enabled: Boolean, onChange: (LocalDateTime) -> Unit) {
    val context = LocalContext.current
    Text(label, fontWeight = FontWeight.Bold)
    Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(6.dp)) {
        OutlinedButton(enabled = enabled, modifier = Modifier.weight(1.3f), contentPadding = PaddingValues(horizontal = 8.dp), onClick = {
            DatePickerDialog(context, { _, y, m, d -> onChange(value.withDayOfMonth(1).withYear(y).withMonth(m + 1).withDayOfMonth(d)) }, value.year, value.monthValue - 1, value.dayOfMonth).show()
        }) { Text(value.format(dateFormat)) }
        OutlinedButton(enabled = enabled, modifier = Modifier.weight(1f), contentPadding = PaddingValues(horizontal = 8.dp), onClick = {
            TimePickerDialog(context, { _, h, m -> onChange(value.withHour(h).withMinute(m).withSecond(0).withNano(0)) }, value.hour, value.minute, true).show()
        }) { Text(value.format(clockFormat)) }
    }
}

@Composable
fun ShiftEditor(existing: Shift?, active: ActiveShift?, reasons: List<String>, busy: Boolean, onDismiss: () -> Unit, onSave: (Shift) -> Unit, onSaveActive: (ActiveShift) -> Unit, initialDate: LocalDate? = null) {
    val initialNow = remember { LocalDateTime.now(israelZone).withSecond(0).withNano(0) }
    var start by remember { mutableStateOf(existing?.let { localTime(it.start) } ?: active?.let { localTime(it.start) } ?: initialDate?.atTime(9,0) ?: initialNow.minusHours(1)) }
    var end by remember { mutableStateOf(existing?.let { localTime(it.end) } ?: initialDate?.atTime(17,0) ?: initialNow) }
    var location by remember { mutableStateOf(existing?.location ?: active?.location ?: OFFICE) }
    var reason by remember { mutableStateOf(existing?.reason ?: active?.reason ?: "") }
    var note by remember { mutableStateOf(existing?.note ?: active?.note ?: "") }
    var error by remember { mutableStateOf<String?>(null) }
    AlertDialog(onDismissRequest = { if (!busy) onDismiss() }, title = { Text(if (active != null) tr(R.string.text_b70622d71d) else if (existing != null) tr(R.string.text_59cb6e8e9a) else tr(R.string.text_10045253c1)) },
        text = { Column(Modifier.verticalScroll(rememberScrollState()), verticalArrangement = Arrangement.spacedBy(10.dp)) {
            Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) { listOf(OFFICE, HOME).forEach { v -> FilterChip(location == v, onClick = { location = v }, enabled = !busy, label = { Text(if (v == "הכול") tr(R.string.filter_all) else locationLabel(v)) }) } }
            DateTimeField(tr(R.string.text_2f6783cd3b), start, !busy) { start = it; error = null }
            DateTimeField(tr(R.string.text_b939061e41), end, !busy) { end = it; error = null }
            if (location == HOME) ReasonField(reason, reasons, !busy) { reason = it }
            OutlinedTextField(note, onValueChange = { note = it.take(5000) }, enabled = !busy, label = { Text(tr(R.string.text_8f9bc2d880)) }, modifier = Modifier.fillMaxWidth(), maxLines = 3)
            Text(tr(R.string.text_1be17082dd), style = MaterialTheme.typography.bodySmall)
            if (active != null) OutlinedButton(enabled = !busy, modifier = Modifier.fillMaxWidth(), onClick = {
                if (timestamp(start) > System.currentTimeMillis()) error = tr(R.string.text_d42c0813fc)
                else onSaveActive(ActiveShift(timestamp(start), location, if (location == HOME) reason.trim() else "", note.trim()))
            }) { Text(tr(R.string.text_510b00fcc4)) }
            error?.let { Text(it, color = MaterialTheme.colorScheme.error) }
        } },
        confirmButton = { TextButton(enabled = !busy, onClick = {
            val a = timestamp(start); val b = timestamp(end)
            error = when { a <= 0 -> tr(R.string.text_647a733fb8); b <= a -> tr(R.string.text_4c82f98655); b > System.currentTimeMillis() -> tr(R.string.text_c2fb808976); else -> null }
            if (error == null) onSave(Shift(id = existing?.id ?: compat.util.UUID.randomUUID().toString(), start = a, end = b, location = location,
                reason = if (location == HOME) reason.trim() else "", note = note.trim(), source = existing?.source ?: "manual",
                workDate = if (existing != null && localTime(existing.start).toLocalDate() == start.toLocalDate()) existing.workDate else start.toLocalDate().toString(),
                recordedDurationMs = if (existing != null && existing.start == a && existing.end == b) existing.recordedDurationMs else null))
        }) { Text(if (busy) tr(R.string.text_0bf5310554) else if (active != null) tr(R.string.text_6eb37ad66f) else tr(R.string.text_e69323393b)) } },
        dismissButton = { TextButton(enabled = !busy, onClick = onDismiss) { Text(tr(R.string.text_a7c55a8d06)) } })
}

@Composable
fun SetupNeeded(onSettings: () -> Unit) {
    Column(Modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) {
        PageTitle(tr(R.string.text_b89e7bee64))
        InfoCard(tr(R.string.text_2eaf74bbd8)) {
            Text(tr(R.string.text_f9fb70ce3b))
            Button(onClick = onSettings) { Text(tr(R.string.text_7c1126f30f)) }
        }
    }
}
